package org.springframework.samples.petclinic.rest.idempotency;

import java.io.IOException;

import org.springframework.http.HttpStatus;
import org.springframework.web.util.ContentCachingResponseWrapper;

import jakarta.servlet.http.HttpServletResponse;

/** The first successful create response, replayed as {@code 200 OK} for later repeats of a key. */
final class StoredResponse {

    private final String contentType;

    private final byte[] body;

    private StoredResponse(String contentType, byte[] body) {
        this.contentType = contentType;
        this.body = body;
    }

    static StoredResponse capturedFrom(ContentCachingResponseWrapper capture) {
        return new StoredResponse(capture.getContentType(), capture.getContentAsByteArray());
    }

    void replayTo(HttpServletResponse response) throws IOException {
        response.reset();
        response.setStatus(HttpStatus.OK.value());
        if (contentType != null) {
            response.setContentType(contentType);
        }
        response.getOutputStream().write(body);
    }
}

